-- Bloco 8/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo III (''Penas e gozos futuros'', itens 133 a 137), qual é a natureza das penas e das alegrias da alma na vida espiritual?', 'São essencialmente morais e inerentes ao grau de elevação ou de imperfeição do próprio Espírito, que carrega em si mesmo o seu céu ou o seu inferno.', 'Consistem em torturas físicas produzidas por caldeiras e chamas materiais.', 'Resumem-se na contemplação imóvel e ociosa sem qualquer atividade útil.', 'Dependem exclusivamente da posição social que o indivíduo ocupou na Terra.', 'São iguais para todos os Espíritos, independentemente de suas obras.', 'A', 'Não tendo mais corpo carnal, o Espírito não sofre torturas físicas exteriores: a felicidade nasce da pureza, do amor e das missões úteis, enquanto o sofrimento decorre do remorso, das paixões não saciadas e da visão de suas vítimas.', 'O Que é o Espiritismo - Cap. III, itens 133 a 137', 'dificil', true),
  ('''o_que_e_espiritismo''', 'Conforme o Capítulo III (item 136), onde estão localizados o céu e o inferno segundo a Doutrina Espírita?', 'O céu fica acima das estrelas fixas e o inferno no centro incandescente da Terra.', 'Em toda parte: o céu está onde há Espíritos felizes e mundos superiores; o inferno está no próprio íntimo dos Espíritos imperfeitos e nos mundos de expiação.', 'O céu localiza-se no Sol e o inferno na superfície da Lua.', 'Ambos são lugares circunscritos cercados por muralhas intransponíveis.', 'Existem apenas como figuras poéticas sem correspondência com o estado da alma.', 'B', 'O céu e o inferno não são lugares geograficamente circunscritos: o Espírito feliz leva consigo a ventura onde quer que esteja, e o Espírito perverso ou impenitente carrega em si mesmo o seu tormento.', 'O Que é o Espiritismo - Cap. III, item 136', 'medio', true),
  ('''o_que_e_espiritismo''', 'De acordo com o Capítulo III (item 137), a que corresponde na Doutrina Espírita a ideia tradicional do purgatório?', 'A um vale escuro onde as almas aguardam passivamente o fim do mundo.', 'A uma prisão subterrânea onde se paga resgate em moedas.', 'Ao estado de erraticidade dolorosa e às encarnações corporais expiatórias em que o Espírito se depura de suas imperfeições.', 'Ao sono letárgico dos Espíritos que desencarnaram na infância.', 'À perda temporária da inteligência nos mundos inferiores.', 'C', 'Kardec explica no item 137 que o purgatório é uma realidade moral: consiste nas dores da erraticidade e nas existências terrestres de prova e expiação pelas quais nos purificamos.', 'O Que é o Espiritismo - Cap. III, item 137', 'facil', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo III (''Intervenção dos Espíritos no mundo corporal'', itens 138 a 143), o que é o Espírito protetor ou Anjo de guarda?', 'Um Espírito inferior encarregado de vigiar os bens materiais da família.', 'Uma força magnética impessoal gerada pelo pensamento humano.', 'Um Espírito que anula o livre-arbítrio do protegido para impedi-lo de errar.', 'Um Espírito de ordem elevada ligado ao indivíduo desde o nascimento para guiá-lo no caminho do bem por meio de bons conselhos.', 'Apenas uma figura alegórica sem existência real no plano espiritual.', 'D', 'Todo homem tem um Espírito protetor (anjo guardião ou bom gênio) de natureza superior, que o assiste com inspirações salutares sem jamais suprimir o seu livre-arbítrio.', 'O Que é o Espiritismo - Cap. III, itens 140 e 141', 'facil', true),
  ('''o_que_e_espiritismo''', 'De acordo com o Capítulo III (itens 142 e 143), qual é o meio mais eficaz de afastar os maus Espíritos e atrair a assistência dos bons?', 'Pronunciar fórmulas latinas de exorcismo e queimar ervas aromáticas.', 'Traçar sinais cabalísticos nas portas e janelas da residência.', 'Evitar qualquer conversa sobre assuntos espirituais ou filosóficos.', 'Portar amuletos metálicos magnetizados por sonâmbulos.', 'Praticar o bem, confiar em Deus, elevar o pensamento pela prece sincera e vencer as próprias imperfeições morais.', 'E', 'Os maus Espíritos são atraídos pelas nossas próprias paixões (orgulho, egoísmo, ódio, cobiça); nenhuma fórmula exterior os afasta se o homem não se reformar moralmente.', 'O Que é o Espiritismo - Cap. III, itens 142 e 143', 'facil', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo III (''Causas anteriores das aflições'', itens 144 a 148), onde reside a causa da maioria das aflições terrenas?', 'Na própria conduta imprudente, orgulhosa ou egoísta do homem na vida presente; e, quando não têm causa atual, nas faltas cometidas em existências anteriores.', 'Na fatalidade cega do destino contra a qual o homem nada pode fazer.', 'No pecado original cometido por um único casal no início dos tempos.', 'Na influência maléfica dos cometas sobre a atmosfera terrestre.', 'No capricho arbitrário da Providência ao distribuir dores sem motivo.', 'A', 'Kardec distingue duas fontes de aflições: 1ª as que o homem cria nesta própria vida por sua imprevidência e más paixões; 2ª as que atingem o homem de bem sem causa atual aparente, que são expiações de vidas passadas.', 'O Que é o Espiritismo - Cap. III, itens 144 a 148', 'expert', true),
  ('''o_que_e_espiritismo''', 'No Capítulo III (itens 146 a 148), por que a justiça divina exige que a falta cometida em uma existência seja reparada por uma expiação equivalente?', 'Porque Deus sente prazer em vingar-se das criaturas que erraram.', 'Porque cada Espírito é solidário com o seu próprio passado, e a expiação ensina pela experiência da dor aquilo que ele fez outros sofrerem.', 'Porque os Espíritos Superiores cobram tributos proporcionais a cada erro.', 'Porque o arrependimento sincero não tem nenhum valor perante as leis morais.', 'Porque somente o sofrimento físico cria a inteligência no Espírito.', 'B', 'Quem abusou da riqueza, do poder ou da saúde aprende, passando pelas provas contrárias, a corrigir o orgulho e a desenvolver a humildade e a caridade.', 'O Que é o Espiritismo - Cap. III, itens 146 a 148', 'dificil', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo III (''Esquecimento do passado'', itens 149 a 152), por que Deus concedeu ao homem encarnado o esquecimento temporário de suas existências anteriores?', 'Para impedir que a humanidade progrida nas ciências e nas artes.', 'Porque o cérebro material não possui espaço físico para guardar lembranças.', 'Porque a lembrança precisa das faltas e inimizades passadas humilharia o homem, perturbaria as relações sociais e entravaria o seu livre-arbítrio.', 'Porque o perispírito apaga definitivamente toda a história do Espírito.', 'Para que ninguém possa jamais acreditar na pluralidade das existências.', 'C', 'O esquecimento temporário durante a vida corpórea é um benefício da sabedoria divina: evita vergonhas paralisantes e ódios perpétuos, permitindo que antigos adversários se reconciliem na mesma família.', 'O Que é o Espiritismo - Cap. III, itens 149 a 152', 'facil', true),
  ('''o_que_e_espiritismo''', 'De acordo com o Capítulo III (itens 151 e 152), embora não tenhamos a lembrança detalhada dos fatos de vidas passadas, o que nos resta delas durante a existência atual?', 'Apenas marcas físicas de nascença na pele.', 'O conhecimento exato do idioma que falamos na encarnação anterior.', 'A memória completa dos nomes e datas de todas as nossas famílias passadas.', 'As tendências instintivas, as aptidões inatas e a voz da consciência, que nos adverte contra os erros já sofridos.', 'Absolutamente nada, nem mesmo no campo intelectual ou moral.', 'D', 'Esquecemos os fatos particulares, mas conservamos o resultado da experiência adquirida sob a forma de ideias inatas, aptidões precoces e intuições morais.', 'O Que é o Espiritismo - Cap. III, itens 151 e 152', 'expert', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo III (itens 153 e 154), como a Doutrina Espírita explica as simpatias e antipatias espontâneas entre pessoas que parecem ver-se pela primeira vez?', 'Pela coincidência da cor dos olhos e do timbre da voz.', 'Pela ação exclusiva da temperatura ambiente no sistema nervoso.', 'Por um sorteio aleatório realizado antes do nascimento.', 'Pela diferença de nacionalidade e de classe financeira.', 'Pela intuição vaga de relações anteriores de afeição ou de animosidade que os Espíritos tiveram em existências passadas ou na erraticidade.', 'E', 'Dois Espíritos que se conheceram — como amigos dedicados ou como inimigos — pressentem-se ao se reencontrarem na carne, gerando simpatia imediata ou repulsão instintiva que o dever moral manda vencer.', 'O Que é o Espiritismo - Cap. III, itens 153 e 154', 'expert', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';